#include <bits/stdc++.h>
using namespace std;struct A{int w,d,z;};A T[1200][2];bool present[1200];vector<int>states;struct C{int idx,pos,halt,h,steps;bitset<512>initial,want;vector<int>visits;};vector<C>cases;int off=128;
bitset<512>parse(string s){bitset<512>t;if(s=="x")return t;istringstream ss(s);string z;while(getline(ss,z,',')){int h=stoi(z)+off;if(h<0||h>=512)throw runtime_error("bounds");t[h]=1;}return t;}
bool clean(int h,const bitset<512>&t){if(h<1||h+64>=512||!t[h-1])return false;for(int i=0;i<h-1;i++)if(t[i])return false;int header=h+52;while(header<512&&!t[header])header++;if(header>=512||header<h+64)return false;int last=511;while(last>=0&&!t[last])last--;int p=header+1,n=0;while(p<last){if(t[p]||!t[p+1])return false;p++;while(p<512&&t[p])p++;n++;}return p==last+1&&n>=10;}
int run(C&c,int a,int b,int mix=-1,bool trace=false){auto mapq=[&](int q){return q==a?b:q;};int q=mapq(84),root=q,h=off;auto tape=c.initial;bitset<1200>seen;int limit=trace?100000:max(10000,c.steps*6+300);for(int step=0;step<=limit;step++){if(step&&((q==root&&clean(h,tape))||q==254)){if(c.halt){if(q==254)return step;}else if(q==root&&h==off+c.h&&tape==c.want)return step;return-1;}if(step==limit||h<0||h>=512||!present[q])return-2;if(trace&&!seen[q]){seen[q]=1;c.visits.push_back(q);}int x=tape[h];A t=T[q==b && x==mix ? a:q][x];tape[h]=t.w;h+=t.d;q=mapq(t.z);}return-2;}
int main(int argc,char**argv){ifstream in(argv[1]);string line;while(getline(in,line)){if(line.empty()||line[0]=='#')continue;istringstream s(line);int q,b,w,z;char d;s>>q>>b>>w>>d>>z;T[q][b]={w,d=='R'?1:-1,z};present[q]=true;}for(int q=0;q<1200;q++)if(present[q])states.push_back(q);ifstream ci(argv[2]);while(getline(ci,line)){istringstream s(line);C c;string x,y;s>>c.idx>>c.pos>>c.halt>>c.h>>x>>y;c.initial=parse(x);c.want=parse(y);c.steps=100000;cases.push_back(c);}vector<int>by[1200];long long baseSteps=0;for(int i=0;i<(int)cases.size();i++){auto&c=cases[i];c.steps=run(c,-1,-1,-1,true);if(c.steps<0){cerr<<"BAD BASE "<<i<<' '<<c.steps<<'\n';return 2;}baseSteps+=c.steps;for(int q:c.visits)by[q].push_back(i);}cerr<<"BASE "<<cases.size()<<" cases "<<baseSteps<<" steps\n";
long long tries=0,screened=0,passed=0;for(int a:states)for(int b:states){if(a>=b)continue;vector<int>v=by[a];v.insert(v.end(),by[b].begin(),by[b].end());sort(v.begin(),v.end());v.erase(unique(v.begin(),v.end()),v.end());vector<int>sample;for(auto u:{by[a],by[b]}){for(int j=0;j<min(4,(int)u.size());j++)sample.push_back(u[j]);if(!u.empty())for(int j=1;j<=8;j++)sample.push_back(u[(u.size()-1)*j/8]);}sort(sample.begin(),sample.end());sample.erase(unique(sample.begin(),sample.end()),sample.end());for(int mix=0;mix<2;mix++){tries++;bool ok=true;for(int i:sample){if(run(cases[i],a,b,mix)<0){ok=false;break;}}if(!ok)continue;screened++;for(int i:v){if(run(cases[i],a,b,mix)<0){ok=false;break;}}if(ok){passed++;cout<<a<<' '<<b<<' '<<mix<<' '<<v.size()<<'\n'<<flush;}}}cerr<<"TRIES "<<tries<<" SAMPLED_PASS "<<screened<<" FULL_PASS "<<passed<<'\n';}
